/* Send Site Notifications to a BCC Address  
 * 
 * Original doc: https://wpmailsmtp.com/docs/sending-site-notifications-to-a-bcc-address/
*/

function wpms_add_bcc_email_address( $args ) {
 
$bcc_address = 'bcc: pattie@example.com';
 
	if ( ! empty( $args[ 'headers' ] ) ) {
		if ( ! is_array( $args[ 'headers' ] ) ) {
			$args[ 'headers' ] = array_filter( explode( "\n", str_replace( "\r\n", "\n", $args[ 'headers' ] ) ) );
		}
	} else {
	$args[ 'headers' ] = [];
	}
 
	$args[ 'headers' ][] = $bcc_address;
 
	return $args;
}
 
add_filter( 'wp_mail', 'wpms_add_bcc_email_address', PHP_INT_MAX );

/* Set a Custom Email Header
 * 
 * Original doc: https://wpmailsmtp.com/docs/setting-a-custom-email-header/
*/

function wpmsmtp_custom_mail_header( $args ) {
	if ( ! is_array( $args[ 'headers' ] ) ) {
		$args[ 'headers' ] = explode( "\n", str_replace( "\r\n", "\n", $args[ 'headers' ] ) );
	}

	$args[ 'headers' ][] = 'X-Custom-Header: header_value';

	return $args;
	}
add_filter ( 'wp_mail', 'wpmsmtp_custom_mail_header');

/* Set a Custom Reply-To Email
 * 
 * Original doc: https://wpmailsmtp.com/docs/setting-a-custom-reply-to-email/
*/

function wp_mail_smtp_dev_reply_to( $args ) {
 
	$reply_to = 'Reply-To: Pattie Paloma <pattie@example.com>';
 
	if ( ! empty( $args[ 'headers' ] ) ) {
		if ( ! is_array( $args[ 'headers' ] ) ) {
			$args[ 'headers' ] = array_filter( explode( "\n", str_replace( "\r\n", "\n", $args[ 'headers' ] ) ) );
	}
 
	// Filter out all other Reply-To headers.
	$args[ 'headers' ] = array_filter( $args[ 'headers' ], function ( $header ) {
		return strpos( strtolower( $header ), 'reply-to' ) !== 0;
	} );
	} else {
		$args[ 'headers' ] = [];
	}

	$args[ 'headers' ][] = $reply_to;

	return $args;
}
 
add_filter( 'wp_mail', 'wp_mail_smtp_dev_reply_to', PHP_INT_MAX );

